    private void inspect(){
        app.eligibility.check(source,result->{if(dead)return;checked=true;canVideo=result.video();canStill=result.still();localVideo=result.info()!=null;videoReason=result.reason();if(!canVideo)videoSelected=false;else if(sceneContent())videoSelected=true;refresh();
            if(sceneContent()&&!canVideo){setStatus("此场景未通过运行检查，无法设置。"+(videoReason.isEmpty()?"":"\n"+videoReason));return;}if(!canStill){setStatus("这个内容暂不能设置为壁纸。");return;}if(!canVideo)setStatus("视频壁纸不允许设置；可选择一帧设置静态壁纸。");
            if(!kind.equals("video")){durationMs=0;selectedUs=0;loadFrame(640);return;}
            worker.submit(()->{try{try(MediaMetadataRetriever reader=new MediaMetadataRetriever()){reader.setDataSource(source.getAbsolutePath());String duration=reader.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);long parsed=Long.parseLong(duration);runOnUiThread(()->{if(dead)return;durationMs=parsed;selectedUs=FrameSelection.clamp(selectedUs,durationMs);chooseFrame(selectedUs);});}}catch(Exception problem){failure(problem);}});
        });
    }
    private void refresh(){
        if(apply==null)return;if(videoUnavailable!=null){videoUnavailable.setVisibility(checked&&!canVideo?View.VISIBLE:View.GONE);videoUnavailable.setText((kind.equals("video")?"视频壁纸":"动态壁纸")+"：不允许设置\n"+(videoReason.isEmpty()?"此内容尚不能由当前引擎运行。":videoReason));}videoChoice.setVisibility(canVideo?View.VISIBLE:View.GONE);stillChoice.setVisibility(canStill?View.VISIBLE:View.GONE);boolean alternatives=canVideo&&canStill;modeHeading.setVisibility(!sceneContent()&&alternatives?View.VISIBLE:View.GONE);modes.setVisibility(!sceneContent()&&canStill?View.VISIBLE:View.GONE);videoChoice.selected(videoSelected);stillChoice.selected(!videoSelected);fillChoice.selected(!fit);fitChoice.selected(fit);
        boolean video=canVideo&&videoSelected;if(!video&&movieRenderer!=null)stopMovie();movie.setVisibility(video?View.VISIBLE:View.GONE);frameControls.setVisibility(canStill&&!video&&kind.equals("video")?View.VISIBLE:View.GONE);if(effectsBox!=null)effectsBox.setVisibility(video&&effectsExpanded?View.VISIBLE:View.GONE);if(effectsHeading!=null)effectsHeading.setVisibility(video?View.VISIBLE:View.GONE);if(retryPreview!=null)retryPreview.setVisibility(video&&previewFailed?View.VISIBLE:View.GONE);if(video&&!busy&&!waiting&&resumed&&movieSurface!=null)startMovie();preview.setScaleType(fit?ImageView.ScaleType.FIT_CENTER:ImageView.ScaleType.CENTER_CROP);pan.setVisibility(View.GONE);scopeHeading.setVisibility((sceneContent()?canVideo:canStill)?View.VISIBLE:View.GONE);scopes.setVisibility((sceneContent()?canVideo:canStill)?View.VISIBLE:View.GONE);scopeNote.setVisibility(video?View.VISIBLE:View.GONE);for(int i=0;i<scopeChoices.length;i++)scopeChoices[i].selected(i==scope);
        boolean usable=sceneContent()?canVideo:canStill;apply.setText(!usable?(checked?"无法设置壁纸":"检查中…"):busy?"正在准备…":video?("设置"+liveLabel()):"设置静态壁纸");apply.setEnabled(usable&&thumbnail!=null&&!frameLoading&&loadedFrameUs==selectedUs&&(!video||movieReady)&&!busy&&!waiting);
    }
    private Bitmap frame(int edge,long timeUs) throws Exception {
        if(!kind.equals("video"))return CanvasWallpaper.poster(source,edge);
        try(MediaMetadataRetriever reader=new MediaMetadataRetriever()){reader.setDataSource(source.getAbsolutePath());int width=Integer.parseInt(reader.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)),height=Integer.parseInt(reader.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));float ratio=Math.min(1,edge/(float)Math.max(width,height));Bitmap image=reader.getScaledFrameAtTime(timeUs,MediaMetadataRetriever.OPTION_CLOSEST,Math.max(1,Math.round(width*ratio)),Math.max(1,Math.round(height*ratio)));if(image==null)throw new IllegalStateException("无法提取视频画面。");return image;}
    }
    private void chooseFrame(long value){if(busy||waiting)return;selectedUs=FrameSelection.clamp(value,durationMs);frameTime.setText(String.format(java.util.Locale.ROOT,"%02d:%02d.%03d / %s",selectedUs/60000000,selectedUs/1000000%60,selectedUs/1000%1000,PlayerControls.time((int)Math.min(Integer.MAX_VALUE,durationMs))));frameSeek.setProgress(durationMs>0?(int)Math.min(frameSeek.getMax(),selectedUs/(durationMs*1000d)*frameSeek.getMax()):0);frameLoading=true;refresh();main.removeCallbacks(loadSelected);main.postDelayed(loadSelected,160);}
    private void loadFrame(int edge){if(dead)return;long request=++frameRequest,time=selectedUs;frameLoading=true;refresh();worker.submit(()->{if(dead||request!=frameRequest)return;try{Bitmap image=frame(edge,time);runOnUiThread(()->{if(dead||request!=frameRequest||time!=selectedUs){image.recycle();return;}Bitmap previous=thumbnail;thumbnail=image;loadedFrameUs=time;frameLoading=false;preview.setImageBitmap(image);if(previous!=null&&previous!=image)previous.recycle();refresh();});}catch(Exception e){runOnUiThread(()->{if(request==frameRequest){frameLoading=false;failure(e);}});}});}
